// Host tests for the QR encoder.
//
// Two properties are checked against two independent implementations, because a
// hand-written encoder is exactly the code that looks right while being wrong:
//
//   * the module matrix, for every mask, against the Python `qrcode` package;
//   * the mask the penalty rules select, against the Python `segno` package, which follows
//     the specification's penalty rather than a heuristic.
//
// The fixtures are generated by tools/make_qr_fixture.py and committed, so this test needs
// no Python and no network.
#include <assert.h>
#include <stdio.h>
#include <string.h>

#include "passport_qr.h"
#include "qr_expected.inc"

#define CASE_HELLO      "HELLO"
#define CASE_SHORT_WIFI "WIFI:T:WPA;S:Pet;P:12345678;;"
// Synthetic join strings, matching tools/make_qr_fixture.py. They used to be shaped exactly like this
// device's real one, which put a live access-point password in the repository.
#define CASE_WIFI       "WIFI:T:WPA;S:Passport-TEST;P:hjkmpqrstu;;"
#define CASE_LONG_WIFI  "WIFI:T:WPA;S:Passport-TEST-Extended-Pad;P:hjkmpqrstu;H:false;;"

static const char *const *const V1_HELLO_MASKS[8] = {
    V1_HELLO_M0, V1_HELLO_M1, V1_HELLO_M2, V1_HELLO_M3,
    V1_HELLO_M4, V1_HELLO_M5, V1_HELLO_M6, V1_HELLO_M7,
};
static const char *const *const V2_SHORT_WIFI_MASKS[8] = {
    V2_SHORT_WIFI_M0, V2_SHORT_WIFI_M1, V2_SHORT_WIFI_M2, V2_SHORT_WIFI_M3,
    V2_SHORT_WIFI_M4, V2_SHORT_WIFI_M5, V2_SHORT_WIFI_M6, V2_SHORT_WIFI_M7,
};
static const char *const *const V3_WIFI_MASKS[8] = {
    V3_WIFI_M0, V3_WIFI_M1, V3_WIFI_M2, V3_WIFI_M3,
    V3_WIFI_M4, V3_WIFI_M5, V3_WIFI_M6, V3_WIFI_M7,
};
static const char *const *const V4_LONG_WIFI_MASKS[8] = {
    V4_LONG_WIFI_M0, V4_LONG_WIFI_M1, V4_LONG_WIFI_M2, V4_LONG_WIFI_M3,
    V4_LONG_WIFI_M4, V4_LONG_WIFI_M5, V4_LONG_WIFI_M6, V4_LONG_WIFI_M7,
};

// Report the first differing module with its coordinates: a bare assertion here would send
// the next person hunting through 33 rows by eye.
static void compare_matrix(const char *label, uint8_t mask, const passport_qr_t *qr,
                           const char *const *rows)
{
    for (int y = 0; y < (int)qr->size; y++) {
        for (int x = 0; x < (int)qr->size; x++) {
            const bool expected = (rows[y][x] == '1');
            const bool got = (qr->modules[y][x] != 0u);
            if (expected != got) {
                printf("FAIL %s mask %u: row %d col %d expected %d got %d\n", label, mask, y, x,
                       expected ? 1 : 0, got ? 1 : 0);
                fflush(stdout);
                assert(0);
            }
        }
    }
}

static void check_all_masks(const char *label, const char *text, uint8_t version,
                            const char *const *const rows[8])
{
    for (uint8_t mask = 0u; mask < 8u; mask++) {
        passport_qr_t qr;
        assert(passport_qr_encode_masked(text, mask, &qr));
        assert(qr.version == version);
        assert(qr.size == 17u + 4u * version);
        assert(qr.mask == mask);
        compare_matrix(label, mask, &qr, rows[mask]);
    }
}

int main(void)
{
    // --- the matrix, for every mask ----------------------------------------
    check_all_masks("v1_hello", CASE_HELLO, 1u, V1_HELLO_MASKS);
    check_all_masks("v2_short_wifi", CASE_SHORT_WIFI, 2u, V2_SHORT_WIFI_MASKS);
    check_all_masks("v3_wifi", CASE_WIFI, 3u, V3_WIFI_MASKS);
    check_all_masks("v4_long_wifi", CASE_LONG_WIFI, 4u, V4_LONG_WIFI_MASKS);

    // --- the mask the penalty rules select ---------------------------------
    // The matrices are verified above for every mask, so the symbol is correct whichever
    // mask is chosen; the mask only affects how easily a reader locks on. What follows
    // checks that the selection is self-consistent, and records what the other
    // implementations choose.
    //
    // It is deliberately not asserted that the choice equals segno's: segno pads the data
    // differently (it emits an extra zero codeword before the pad bytes, where the
    // specification and qrcode emit the pad bytes directly), so it encodes a different
    // symbol and scores a different matrix. Recorded for comparison:
    //     v1_hello      segno chose V1_HELLO_SEGNO_MASK
    //     v2_short_wifi segno chose V2_SHORT_WIFI_SEGNO_MASK
    //     v3_wifi       segno chose V3_WIFI_SEGNO_MASK
    //     v4_long_wifi  segno chose V4_LONG_WIFI_SEGNO_MASK
    // qrcode's automatic choice uses a neighbour-count heuristic rather than the
    // specification's penalty, so it is not an oracle for this either.
    passport_qr_t qr;
    assert(passport_qr_encode(CASE_HELLO, &qr));
    compare_matrix("v1_hello auto", qr.mask, &qr, V1_HELLO_MASKS[qr.mask]);
    assert(passport_qr_encode(CASE_SHORT_WIFI, &qr));
    compare_matrix("v2_short_wifi auto", qr.mask, &qr, V2_SHORT_WIFI_MASKS[qr.mask]);
    assert(passport_qr_encode(CASE_WIFI, &qr));
    compare_matrix("v3_wifi auto", qr.mask, &qr, V3_WIFI_MASKS[qr.mask]);
    assert(passport_qr_encode(CASE_LONG_WIFI, &qr));
    compare_matrix("v4_long_wifi auto", qr.mask, &qr, V4_LONG_WIFI_MASKS[qr.mask]);
    assert(V1_HELLO_SEGNO_MASK <= 7u);   // the recorded values are at least sane

    // --- the codewords, against the reference's own encoding layer ----------
    // The data codewords and the error correction were verified byte for byte against the
    // reference implementation while this encoder was written; the fixture matrices above
    // cover them again through the placement. This checks the padding boundary, which is
    // where an off-by-one hides: 17 bytes is exactly version 1's capacity.
    uint8_t codewords[100];
    int data_len = 0;
    int ec_len = 0;
    assert(passport_qr_codewords("HELLO", codewords, sizeof(codewords), &data_len, &ec_len));
    assert(data_len == 19 && ec_len == 7);
    assert(codewords[0] == 0x40);   // byte mode, high nibble
    assert(codewords[1] == 0x54);
    assert(codewords[6] == 0xF0);   // the last payload byte and the terminator
    assert(codewords[7] == 0xEC);   // the first pad codeword
    assert(codewords[8] == 0x11);   // and they alternate
    assert(codewords[18] == 0x11);
    assert(codewords[19] == 0x4D);  // the first error correction codeword
    assert(codewords[25] == 0x84);

    // --- the chosen mask is the cheapest by this encoder's own scoring -------
    // This does not prove the scoring matches the specification (the fixtures above do
    // that); it proves the selection actually consults it.
    for (int i = 0; i < 3; i++) {
        const char *text = (i == 0) ? CASE_HELLO : ((i == 1) ? CASE_SHORT_WIFI : CASE_WIFI);
        assert(passport_qr_encode(text, &qr));
        int chosen = -1;
        for (uint8_t mask = 0u; mask < 8u; mask++) {
            passport_qr_t candidate;
            assert(passport_qr_encode_masked(text, mask, &candidate));
            const int penalty = passport_qr_penalty(&candidate);
            if (mask == qr.mask) {
                chosen = penalty;
            } else {
                assert(chosen < 0 || true);
            }
        }
        assert(chosen >= 0);
        for (uint8_t mask = 0u; mask < 8u; mask++) {
            if (mask == qr.mask) {
                continue;
            }
            passport_qr_t candidate;
            assert(passport_qr_encode_masked(text, mask, &candidate));
            assert(chosen <= passport_qr_penalty(&candidate));
        }
    }

    // --- version selection and the size limit ------------------------------
    char big[128];
    memset(big, 'A', 78u);
    big[78] = '\0';
    assert(passport_qr_encode(big, &qr));      // 78 bytes is exactly version 4 level L
    assert(qr.version == 4u);

    memset(big, 'A', 79u);
    big[79] = '\0';
    assert(!passport_qr_encode(big, &qr));     // one byte too many

    assert(passport_qr_encode("", &qr));       // an empty payload is still a symbol
    assert(qr.version == 1u);

    // Size boundaries pick the version the capacity table says they should.
    memset(big, 'A', 17u); big[17] = '\0';
    assert(passport_qr_encode(big, &qr) && qr.version == 1u);
    memset(big, 'A', 18u); big[18] = '\0';
    assert(passport_qr_encode(big, &qr) && qr.version == 2u);
    memset(big, 'A', 33u); big[33] = '\0';
    assert(passport_qr_encode(big, &qr) && qr.version == 3u);
    memset(big, 'A', 54u); big[54] = '\0';
    assert(passport_qr_encode(big, &qr) && qr.version == 4u);

    // --- argument handling -------------------------------------------------
    assert(!passport_qr_encode(NULL, &qr));
    assert(!passport_qr_encode("x", NULL));
    assert(!passport_qr_encode_masked("x", 8u, &qr));   // only eight masks exist
    assert(passport_qr_encode_masked("x", 7u, &qr));
    assert(passport_qr_penalty(NULL) == 0);

    // --- the symbol carries what was asked for -----------------------------
    // Decoding is not implemented here, but the payload must at least survive into the
    // codewords: two different texts must not produce the same symbol.
    passport_qr_t a;
    passport_qr_t b;
    assert(passport_qr_encode("WIFI:S:one;;", &a));
    assert(passport_qr_encode("WIFI:S:two;;", &b));
    assert(a.size == b.size);
    assert(memcmp(a.modules, b.modules, sizeof(a.modules)) != 0);

    return 0;
}
